export type ParsedInitializeConfigInstruction<
  TProgram extends string = typeof PAYCHECK_ROUTER_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    deployer: TAccountMetas[0];
    config: TAccountMetas[1];
    program: TAccountMetas[2];
    programData: TAccountMetas[3];
    usdcMint: TAccountMetas[4];
    treasury: TAccountMetas[5];
    usdcTokenProgram: TAccountMetas[6];
    systemProgram: TAccountMetas[7];
  };
  data: InitializeConfigInstructionData;
};

export function parseInitializeConfigInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedInitializeConfigInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 8,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      deployer: getNextAccount(),
      config: getNextAccount(),
      program: getNextAccount(),
      programData: getNextAccount(),
      usdcMint: getNextAccount(),
      treasury: getNextAccount(),
      usdcTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getInitializeConfigInstructionDataDecoder().decode(instruction.data),
  };
}
